{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Prazosin-related PET tracers with heteroaromatic and amine-containing structures showed limited BBB permeability and were unsuitable for neuroimaging, supporting poor CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A piperidine-containing benzamide PET tracer showed very low initial brain uptake in mice, indicating that related polar/amine-rich structures do not achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sacubitril in cynomolgus monkeys had a CSF:plasma ratio ≤0.0044 and brain:plasma ratio ≤0.0326, demonstrating that even systemically bioavailable compounds can have negligible CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Bunitrolol, which shares an aryloxypropanolamine-like motif with the query, showed low distribution to brain relative to other tissues, supporting limited CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A related amide/heteroaryl compound had a brain/blood concentration ratio of 0.02 in mice, directly indicating very poor brain penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to lack meaningful CNS access because multiple high-transfer experimental records, including direct brain/CSF measurements and PET biodistribution studies, consistently show poor BBB penetration for structurally and physicochemically related molecules.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query itself.",
    "No transporter efflux data (P-gp/BCRP) for the query.",
    "No unbound brain concentration or Kp,uu value available.",
    "Query-specific permeability has not been experimentally determined."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

